from dataclasses import dataclass
import math


@dataclass
class ActuatorCommand:
    name: str
    velocity: float = 0.0


def _drive_value(signal, side):
    if not isinstance(signal, dict):
        raise TypeError(f"{side}_signal must be a dictionary")
    if "samples" not in signal:
        raise TypeError(f"{side}_signal requires samples")
    samples = signal["samples"]
    if not isinstance(samples, (list, tuple)):
        raise TypeError("samples must be a list or tuple")
    if not samples:
        raise ValueError("samples must not be empty")
    checked = []
    for sample in samples:
        if isinstance(sample, bool) or not isinstance(sample, (int, float)):
            raise TypeError("samples must be numeric")
        if not math.isfinite(sample):
            raise ValueError("samples must be finite")
        checked.append(sample)
    mean = sum(checked) / len(checked)
    return max(-1.0, min(1.0, mean)) * 6.0


def mix_drive(left_signal, right_signal):
    commands = [
        ActuatorCommand("cart/rear_port"),
        ActuatorCommand("cart/rear_starboard"),
        ActuatorCommand("cart/front_port"),
        ActuatorCommand("cart/front_starboard"),
    ]
    if left_signal is None or right_signal is None:
        return commands

    left = _drive_value(left_signal, "left")
    right = _drive_value(right_signal, "right")
    commands[0].velocity = left
    commands[1].velocity = right
    commands[2].velocity = left
    commands[3].velocity = left
    return commands

